-- S3 dry run (docs/launch/S3-dryrun.md): the read-only queries behind the report. SELECT only; no write was made.
-- Save the result of query 1 as .claude/s3-live.json (jsonb value of column r; the tool writes it to a file when large).
-- The result holds account and money-row ids cut to 8 characters, never message text. Keep it under .claude/ (git-ignored).

-- 1. The live money rows of every message (deleted ones too), and per-log facts. Users u1..uN are numbered as in sms-s2c-replay-inputs.sql.
with users as (select user_id, 'u' || dense_rank() over (order by user_id) as u from (select distinct user_id from sms_parse_log) d)
select jsonb_build_object(
 'users', (select jsonb_object_agg(u, left(user_id::text,8)) from users),
 'exp', (select jsonb_agg(jsonb_build_array(left(e.sms_log_id::text,8), left(e.id::text,8), e.category::text, e.amount::text, e.currency::text, e.expense_date::text, to_char(e.occurred_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'), left(e.payment_method_id::text,8), left(e.to_payment_method_id::text,8), e.refund_kind, left(e.refund_sms_log_id::text,8), (e.refunded_at is not null), e.spend_exclusion, e.sms_flags, e.sms_flags_ack, to_char(e.deleted_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'), left(e.retracted_by_sms_log_id::text,8), to_char(e.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'), to_char(e.edited_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'), (e.notes is not null), l.category, (e.payment_method_id is distinct from l.payment_method_id), (e.description is distinct from l.clean_title and e.description is distinct from l.merchant_normalized and e.description is distinct from l.merchant), e.description = 'Transfer fee', e.is_debt_payment, left(e.linked_debt_id::text,8), left(e.user_id::text,8)) order by e.sms_log_id, e.created_at) from expenses e join sms_parse_log l on l.id=e.sms_log_id),
 'inc', (select jsonb_agg(jsonb_build_array(left(i.sms_log_id::text,8), left(i.id::text,8), i.source_type::text, i.amount::text, i.currency::text, i.received_date::text, i.occurrence_date::text, left(i.payment_method_id::text,8), i.exclusion, i.sms_flags, i.sms_flags_ack, to_char(i.deleted_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'), left(i.retracted_by_sms_log_id::text,8), to_char(i.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'), to_char(i.edited_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'), (i.notes is not null), left(i.linked_debt_id::text,8), left(i.template_id::text,8), i.status::text, left(i.user_id::text,8)) order by i.sms_log_id, i.created_at) from income_events i where i.sms_log_id is not null),
 'logs', (select jsonb_agg(jsonb_build_array(left(l.id::text,8), left(l.user_id::text,8), l.status, (l.confirmed_at is not null), l.awaiting_confirmation, l.own_transfer_verdict, l.bank_source, l.format_key, l.shape_key, (l.template_revoked_at is not null), left(l.matched_template_id::text,8), l.parse_method, (l.raw_body is not null), l.balance_after is not null, to_char(l.received_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'), l.bank_name, l.sender, l.discard_requested_at is not null, l.wording_guard_hit, left(l.expense_id::text,8), left(l.income_id::text,8)) order by l.id) from sms_parse_log l)
) as r;

-- 2. Carried items: which rows lack the new columns, and revoked templates.
-- select (masked_body is not null) has_masked, (raw_body is not null) has_raw, bank_source is null no_bank_source, format_key is null no_format_key, shape_key is null no_shape_key, (template_revoked_at is not null) revoked, count(*) from sms_parse_log group by 1,2,3,4,5,6 order by 7 desc;

-- 3. Stored time zones of the users (the day-shift check).
-- select left(s.user_id::text,8) u8, s.timezone from user_settings s where s.user_id in (select distinct user_id from sms_parse_log) order by 1;

-- 4. User-touch signals: edited_at is set on every row, so only the deletion, notes, exclusion and acknowledgement columns are used.
-- select 'exp' t, (deleted_at is not null) del, (retracted_by_sms_log_id is not null) retr, (notes is not null) has_notes, (spend_exclusion is not null) excl, (sms_flags_ack is not null and cardinality(sms_flags_ack)>0) acked, count(*) from expenses where sms_log_id is not null group by 2,3,4,5,6;

-- 5. Template promotion export (.claude/sms-replay-raw.json, git-ignored; raw text exists for recent rows only), run by
--    TZ=Africa/Cairo npx vitest run src/lib/sms/gold/templateReplay.test.ts --reporter=verbose
-- with users as (select user_id, 'u' || dense_rank() over (order by user_id) u from (select distinct user_id from sms_parse_log) d)
-- select jsonb_build_object('templates', (select jsonb_agg(jsonb_build_object('id', t.id, 'sender', t.sender, 'regex', t.regex_pattern, 'rules', t.mapping_rules, 'tier', t.tier, 'status', t.status, 'ai_enabled', t.ai_enabled, 'match_count', t.match_count, 'users', t.unique_user_count, 'failures', t.failure_count, 'hard_fail', t.hard_fail, 'age_days', floor(extract(epoch from (now()-t.created_at))/86400), 'contributors', (select coalesce(jsonb_agg(distinct u2.u), '[]'::jsonb) from (select u.u from sms_parse_log l join users u on u.user_id=l.user_id where l.matched_template_id=t.id union select u.u from users u where u.user_id=t.user_id) u2))) from sms_tracking_templates_ai t),
--   'rows', (select jsonb_agg(jsonb_build_object('id', left(l.id::text,8), 'u', u.u, 'raw', l.raw_body, 'mb', l.masked_body, 'ok', coalesce(l.parsed_ok,false), 'st', l.status, 'fc', l.failure_code, 'pm', l.parse_method, 'k', l.kind, 'a', l.amount, 'c', l.currency, 't', l.account_last4, 'tid', l.matched_template_id, 'dup', coalesce(l.is_duplicate,false))) from sms_parse_log l join users u on u.user_id=l.user_id)) r;

-- 6. The capped balance check on b61afd88 (its raw text exists until about 2026-11-25). Read the figures in the tool result; never copy them or the text into a file.
-- select left(id::text,8) id, kind, amount, (select array_agg(m[1]) from regexp_matches(raw_body, '(\d+(?:[.,]\d+)?)', 'g') m) nums from sms_parse_log where id::text like any (array['b61afd88%']);
-- and the same user's rows around it on the same card: select left(id::text,8), kind, amount, balance_after, account_last4, received_at, (raw_body is not null) from sms_parse_log where user_id = (select user_id from sms_parse_log where id::text like 'b61afd88%') and received_at between (select received_at from sms_parse_log where id::text like 'b61afd88%') - interval '4 days' and (select received_at from sms_parse_log where id::text like 'b61afd88%') + interval '4 days' and (balance_after is not null or account_last4 = (select account_last4 from sms_parse_log where id::text like 'b61afd88%'));
